'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrapcorr = require( '@stdlib/stats/incr/apcorr' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a sample absolute Pearson product-moment correlation coefficient, ignoring `NaN` values.
*
* @param {number} [meanx] - mean value
* @param {number} [meany] - mean value
* @throws {TypeError} first argument must be a number
* @throws {TypeError} second argument must be a number
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanapcorr();
*
* var ar = accumulator();
* // returns null
*
* ar = accumulator( 2.0, 1.0 );
* // returns 0.0
*
* ar = accumulator( NaN, 1.0 );
* // returns 0.0
*
* ar = accumulator( -5.0, 3.14 );
* // returns ~1.0
*
* ar = accumulator();
* // returns ~1.0
*
* @example
* var accumulator = incrnanapcorr( 2.0, -3.0 );
*/
function incrnanapcorr( meanx, meany ) {
	var acc;
	if ( arguments.length ) {
		acc = incrapcorr( meanx, meany );
	} else {
		acc = incrapcorr();
	}
	return accumulator;

	/**
	* If provided input values, the accumulator function returns an updated sample correlation coefficient. If not provided input values, the accumulator function returns the current sample correlation coefficient.
	*
	* @private
	* @param {number} [x] - new value
	* @param {number} [y] - new value
	* @returns {(number|null)} sample absolute correlation coefficient or null
	*/
	function accumulator( x, y ) {
		if ( arguments.length === 0 || isnan( x ) || isnan( y ) ) {
			return acc();
		}
		return acc( x, y );
	}
}


// EXPORTS //

module.exports = incrnanapcorr;
